// BidLockOracleData.hpp - oracle rows of the bid lock guard (plan 4.1), generated by EXECUTING the real Windows code
// (Windows 49a2d59, read-only: python -B -I, imported in memory, sqlite3 in memory; nothing written into the Windows tree):
//   ost_visualizer/domain/entities/cover_sheet.py:15-23      resolve_bid_status_lock  (tables 1 and 3)
//   ost_visualizer/application/services/project_read_service.py:81-94  is_bid_locked  (tables 1 and 2: the answer below)
//   ost_visualizer/infrastructure/mdb/components/settings_reader.py:63-77  _parse_job_statuses (the Locked rule at :71,
//     `Locked not in ("0", "False", "")` on the serialized text, a NULL serializes as "NULL" and so reads LOCKED) and :361-370
//     get_job_statuses (a duplicate JobStatuses UID or any failed read gives an EMPTY list, i.e. unresolved)
//   ost_visualizer/infrastructure/parsers/ost_serializer.py:18-61  serialize_value / serialize_row (None -> "NULL", int -> decimal text)
// The rows go through the real reader, serializer and service on an in-memory sqlite database whose DDL is the one the Windows tests
// use (tests/infrastructure/mdb/components/test_settings_reader.py:892-910: Locked untyped); the C++ tests create the SAME DDL:
//   CREATE TABLE Bids (UID INTEGER, JobStatusUID)
//   CREATE TABLE JobStatuses (UID INTEGER, Name TEXT, Locked, Sequence INTEGER)
// The generator was a throw-away script run against the Windows tree (not in this repository, like the other oracle generators).
// Literals are SQL literals (what goes after VALUES). `locked` is the answer of is_bid_locked (an unresolved status is locked).
#pragma once

#include <vector>

namespace ost_ptest
{
    namespace bidlock
    {
        struct StatusLiteral
        {
            const char *uid;    // SQL literal of JobStatuses.UID
            const char *locked; // SQL literal of JobStatuses.Locked
        };

        // Table 1: one status (uid 5) with this Locked value, the bid points at it. Windows is_bid_locked answer in `locked`.
        struct FlagRow
        {
            const char *locked_literal;
            bool locked;
        };

        // Table 2: which status the bid points at. `locked` is is_bid_locked (project_read_service.py:81-94); `with_status_table` is false
        // when the JobStatuses table does not exist at all.
        struct ResolveRow
        {
            const char *name;
            std::vector<StatusLiteral> statuses;
            const char *bid_status_literal;
            bool with_status_table;
            bool locked;
        };

        // Table 3: the pure rule on a status list. status text ""/has_status=false stands for None. `result`: 'T' locked, 'F' unlocked,
        // 'N' unresolved (Windows None).
        struct PureStatus
        {
            const char *uid;
            bool locked;
        };
        struct PureRow
        {
            const char *name;
            std::vector<PureStatus> statuses;
            bool has_status; // false: the bid status is None
            const char *status_uid;
            char result;
        };

        inline const std::vector<FlagRow> &flag_rows()
        {
            static const std::vector<FlagRow> rows = {
                {"0", false},
                {"1", true},
                {"-1", true},
                {"2", true},
                {"-2", true},
                {"1000", true},
                {"NULL", true},
                {"'False'", false},
                {"''", false},
                {"'True'", true},
                {"'0'", false},
                {"'1'", true},
                {"'-1'", true},
                {"'false'", true},
                {"'FALSE'", true},
                {"' 0'", true},
                {"'0 '", true},
                {"'00'", true},
                {"'0.0'", true},
                {"'-0'", true},
                {"'No'", true},
                {"'x'", true},
                {"'NULL'", true},
                {"' '", true},
                {"'Yes'", true},
            };
            return rows;
        }

        inline const std::vector<ResolveRow> &resolve_rows()
        {
            static const std::vector<ResolveRow> rows = {
                {"no status NULL, no statuses", {}, "NULL", true, false},
                {"no status NULL, locked statuses present", {{"1", "-1"}, {"0", "-1"}}, "NULL", true, false},
                {"no status empty text", {{"1", "-1"}}, "''", true, false},
                {"no status NULL, no JobStatuses table", {}, "NULL", false, false},
                {"status 1 open", {{"1", "0"}, {"2", "-1"}}, "1", true, false},
                {"status 2 locked", {{"1", "0"}, {"2", "-1"}}, "2", true, true},
                {"status 3 unknown", {{"1", "0"}, {"2", "-1"}}, "3", true, true},
                {"status 0 unknown", {{"1", "0"}, {"2", "-1"}}, "0", true, true},
                {"status -1 unknown", {{"1", "0"}, {"2", "-1"}}, "-1", true, true},
                {"status '01' is not 1 (text compare)", {{"1", "0"}, {"2", "-1"}}, "'01'", true, true},
                {"status '007' text vs uid 7", {{"7", "0"}}, "'007'", true, true},
                {"status '7' text equals uid 7", {{"7", "0"}}, "'7'", true, false},
                {"status '2' text equals uid 2 (locked)", {{"1", "0"}, {"2", "-1"}}, "'2'", true, true},
                {"status ' 2' (space) is not 2", {{"2", "-1"}}, "' 2'", true, true},
                {"status 'abc' unknown", {{"1", "0"}}, "'abc'", true, true},
                {"status 0 exists and is open", {{"1", "-1"}, {"0", "0"}}, "0", true, false},
                {"status 0 exists and is locked", {{"1", "0"}, {"0", "-1"}}, "0", true, true},
                {"empty status table, status 3", {}, "3", true, true},
                {"empty status table, status 0", {}, "0", true, true},
                {"no JobStatuses table, status 3", {}, "3", false, true},
                {"duplicate uid 7, bid 7 (open first)", {{"7", "0"}, {"7", "-1"}}, "7", true, true},
                {"duplicate uid 7, bid 7 (locked first)", {{"7", "-1"}, {"7", "0"}}, "7", true, true},
                {"duplicate uid 8 spoils unique uid 7", {{"7", "0"}, {"8", "0"}, {"8", "-1"}}, "7", true, true},
                {"duplicate uid 7 but the bid has no status", {{"7", "0"}, {"7", "-1"}}, "NULL", true, false},
                {"duplicate as text and integer", {{"7", "0"}, {"'7'", "0"}}, "7", true, true},
                {"NULL uid row next to uid 3 (locked)", {{"NULL", "0"}, {"3", "-1"}}, "3", true, true},
                {"NULL uid row, unknown status 1", {{"NULL", "0"}, {"3", "-1"}}, "1", true, true},
                {"two NULL uid rows are duplicates", {{"NULL", "0"}, {"NULL", "0"}}, "3", true, true},
                {"one status among several: only the matching row counts", {{"1", "-1"}, {"2", "0"}, {"3", "-1"}}, "2", true, false},
            };
            return rows;
        }

        inline const std::vector<PureRow> &pure_rows()
        {
            static const std::vector<PureRow> rows = {
                {"cs:19 no status None, no statuses", {}, false, "", 'F'},
                {"cs:19 no status empty, no statuses", {}, true, "", 'F'},
                {"cs:19 no status None, one locked", {{"1", true}}, false, "", 'F'},
                {"cs:19 no status empty, one locked", {{"1", true}}, true, "", 'F'},
                {"cs:19 no status None, empty and zero uid", {{"", true}, {"0", true}}, false, "", 'F'},
                {"cs:19 no status empty, empty and zero uid", {{"", true}, {"0", true}}, true, "", 'F'},
                {"cs:26 unknown 3", {{"1", false}, {"2", true}}, true, "3", 'N'},
                {"cs:26 unknown 0", {{"1", false}, {"2", true}}, true, "0", 'N'},
                {"cs:26 unknown 01", {{"1", false}, {"2", true}}, true, "01", 'N'},
                {"cs:26 unknown -1", {{"1", false}, {"2", true}}, true, "-1", 'N'},
                {"cs:31 no statuses, 1", {}, true, "1", 'N'},
                {"cs:32 no statuses, 0", {}, true, "0", 'N'},
                {"cs:36 matching 1", {{"1", true}, {"2", false}, {"3", true}}, true, "1", 'T'},
                {"cs:36 matching 2", {{"1", true}, {"2", false}, {"3", true}}, true, "2", 'F'},
                {"cs:36 matching 3", {{"1", true}, {"2", false}, {"3", true}}, true, "3", 'T'},
                {"cs:41 zero uid exists, locked", {{"1", false}, {"0", true}}, true, "0", 'T'},
                {"cs:41 zero uid exists, open", {{"1", true}, {"0", false}}, true, "0", 'F'},
                {"cs:55 first match wins (locked first)", {{"2", true}, {"2", false}}, true, "2", 'T'},
                {"cs:55 first match wins (open first)", {{"2", false}, {"2", true}}, true, "2", 'F'},
                {"cs:66 stored 2 requested ' 2'", {{"2", true}}, true, " 2", 'N'},
                {"cs:66 stored 2 requested '2 '", {{"2", true}}, true, "2 ", 'N'},
                {"cs:66 stored ' 2' requested 2", {{" 2", true}}, true, "2", 'N'},
                {"cs:66 stored '2 ' requested 2", {{"2 ", true}}, true, "2", 'N'},
                {"cs:66 stored a requested A", {{"a", true}}, true, "A", 'N'},
                {"cs:66 stored A requested a", {{"A", true}}, true, "a", 'N'},
                {"cs:78 stored ' 2' requested ' 2'", {{" 2", true}}, true, " 2", 'T'},
                {"cs:80 a status called None is not matched by a missing status", {{"None", true}}, false, "", 'F'},
                {"cs:83 'none' lower case does not match", {{"None", true}}, true, "none", 'N'},
                {"extra: the text None matches a status called None", {{"None", true}}, true, "None", 'T'},
                {"extra: an empty uid status never matches a real uid", {{"", true}}, true, "1", 'N'},
                {"extra: open status with locked neighbours", {{"1", true}, {"2", false}}, true, "2", 'F'},
            };
            return rows;
        }
    }
}
